import difflib,hashlib,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
before=json.loads((OUT/'protected-before.json').read_text());changed=[p for p,h in before.items() if not Path(p).is_file() or sha(Path(p))!=h]
prod=json.loads((OUT/'production-before.json').read_text());modified=[str(Path(p).relative_to(ROOT)) for p,h in prod.items() if sha(Path(p))!=h]
allowed=['local_api/services/record_relationships.py','scripts/single_resume_pipeline.py']
assert not changed and sorted(modified)==sorted(allowed)
result={'protected_files_checked':len(before),'protected_files_changed':changed,'scope':'Pre-existing report/ground-truth/fixture files excluding runtime __pycache__, plus ten selected original PDFs. Original 350 artifacts included.','existing_code_files_modified':modified,'approved_existing_code_files':allowed,'new_regression_file':'tests/test_phase1_repairs.py','unexpected_existing_code_changes':[],'original_pdfs_and_frozen_inventories_preserved':True,'new_provider_calls':0,'ten_input_replay_pdf_extractions':0,'ten_input_replay_section_detections':0,'ten_input_replay_embeddings':0,'previous_350_experiment_rerun':False,'chunking_implemented':False,'education_policy_changed':False,'code_hashes_after':{k:sha(ROOT/k) for k in allowed+['tests/test_phase1_repairs.py']}}
(OUT/'preservation-check.json').write_text(json.dumps(result,indent=2)+'\n')
focused='AUDIT_TEST_LABEL=focused- PYTHONUNBUFFERED=1 .venv/bin/python reports/ten-resume-phase1-20261024/run_tests_offline.py tests/test_phase1_repairs.py tests/test_record_subfields.py tests/test_structural_grouping.py tests/test_single_resume_check.py tests/test_llm_section_review.py tests/test_section_subschemas.py reports/ten-resume-repair-plan-20261024/tests/test_confirmed_defects.py'
full='AUDIT_TEST_LABEL=full- PYTHONUNBUFFERED=1 .venv/bin/python reports/ten-resume-phase1-20261024/run_tests_offline.py'
log='Phase 1 exact test commands and results\n\n1. Original red tests before editing production:\nDEEPSEEK_API_KEY=\'\' DEEPSEEK_REVIEW_ENABLED=false .venv/bin/python -m pytest -q reports/ten-resume-repair-plan-20261024/tests/test_confirmed_defects.py\n'+(OUT/'red-tests.txt').read_text()
log+='\n2. Corrected expanded tests against hash-verified pre-fix module copies:\n.venv/bin/python reports/ten-resume-phase1-20261024/run_corrected_before_tests.py\n'+(OUT/'corrected-before-tests.txt').read_text()
log+='\n3. Completed focused tests (outside sandbox with offline network guard):\n'+focused+'\n'+(OUT/'focused-tests.txt').read_text()
log+='\n4. Completed full suite (outside sandbox with offline network guard):\n'+full+'\n'+(OUT/'full-tests.txt').read_text()
log+='\nNetwork guard logs:\n'+(OUT/'focused-network-guard.txt').read_text()+(OUT/'full-network-guard.txt').read_text()
log+='\nInitial expanded test runs had a newly written fixture missing page_number: those logs are retained in new-tests-before.txt and focused-initial.txt. The fixture was corrected, not the expected behavior weakened. The completed runs above pass, including both original defect regressions. The pre-fix expanded run excludes only an integration test with an inline current-code import; original red tests reproduced both defects. No failed production expectation was excluded from the completed focused or full suite.\n\nThe 108 focused tests overlap the full suite; two original investigation tests live outside tests/ and are included in focused results. The full suite has 434 tests, zero failures/errors/skips. No network attempts in either completed guard log. Running outside the sandbox follows the already documented TestClient hang diagnosis; credentials are removed by the guard and cached models are offline.\n\nOffline replay commands:\n.venv/bin/python reports/ten-resume-phase1-20261024/prepare_baseline.py\n# Executed before production edits; isolated before/ and preservation snapshots.\n.venv/bin/python - <<\'PY\'\nimport importlib.util\nfrom pathlib import Path\np=Path(\'reports/ten-resume-phase1-20261024/prepare_baseline.py\')\nspec=importlib.util.spec_from_file_location(\'phase1_replay\',p)\nmod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)\nmod.replay(p.parent/\'after\')\nPY\n.venv/bin/python reports/ten-resume-phase1-20261024/compare.py\n# Ten before maps reproduce frozen schemas exactly; ten after maps pass source/hierarchy checks; 17/17 partial expected tuples unchanged. Original source files never rewritten.\n'
(OUT/'test-results.txt').write_text(log)
patch=subprocess.check_output(['git','diff','--',*allowed],cwd=ROOT).decode()
patch+=''.join(difflib.unified_diff([], (ROOT/'tests/test_phase1_repairs.py').read_text().splitlines(keepends=True),fromfile='/dev/null',tofile='tests/test_phase1_repairs.py'))
(OUT/'phase1.patch').write_text(patch)
readiness=OUT/'readiness-assessment.md';readiness.write_text(readiness.read_text()+f'\nVerification completed: 108 focused checks and 434 full-suite checks passed (zero failures/skips); zero external socket attempts. Preservation verified {len(before):,} protected files unchanged; exactly the two approved existing code files changed. No chunking or extra API calls.\n')
files=[p for p in OUT.rglob('*') if p.is_file()]
(OUT/'created-files.json').write_text(json.dumps({'files':[{'path':str(p.relative_to(ROOT)),'sha256':sha(p)} for p in sorted(files)],'self_hash_excluded':True},indent=2)+'\n')
print(json.dumps(result,indent=2))
